// File: ChipsOracle.sol


pragma solidity ^0.8.0;





contract PaymentOracle is Pausable {
    using SafeERC20 for IERC20;

    address public immutable owner;

    struct TokenInfo {
        address tokenAddress;
        AggregatorV3Interface priceFeed;
        bool isStablecoin;
        uint8 decimals;
    }

    mapping(uint256 => TokenInfo) public tokens;
    mapping(uint256 => uint256) public cTokenUsdPrices;
    uint256 public currencyCount;

    event PaymentMade(
        address indexed user,
        uint256 indexed payTokenType,
        uint256 indexed cTokenType,
        string kAddress,
        uint256 itemCount
    );

    constructor(
        address _usdc,
        address _usdt,
        address _wbtc,
        address _weth,
        address _ethPriceFeed,
        address _wbtcPriceFeed,
        address _wethPriceFeed
    ) {
        owner = msg.sender;
        currencyCount = 5;

        tokens[1] = TokenInfo(address(0), AggregatorV3Interface(_ethPriceFeed), false, 18);
        tokens[2] = TokenInfo(_usdc, AggregatorV3Interface(address(0)), true, 6);
        tokens[3] = TokenInfo(_usdt, AggregatorV3Interface(address(0)), true, 6);
        tokens[4] = TokenInfo(_wbtc, AggregatorV3Interface(_wbtcPriceFeed), false, 8);
        tokens[5] = TokenInfo(_weth, AggregatorV3Interface(_wethPriceFeed), false, 18);

        cTokenUsdPrices[1] = 2850; // cKDA
        cTokenUsdPrices[2] = 2300; // cBTC
        cTokenUsdPrices[3] = 11900; // cLTC
        cTokenUsdPrices[4] = 2150; // cKAS
        cTokenUsdPrices[5] = 2590; //icBTC
        cTokenUsdPrices[6] = 3850; //icBTC
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    function getLatestPrice(uint256 payTokenType) public view returns (uint256) {
        TokenInfo storage token = tokens[payTokenType];
        require(address(token.priceFeed) != address(0), "No price feed for this token");
        
        (,int256 price,,,) = token.priceFeed.latestRoundData();
        require(price > 0, "Invalid price feed response");
        return uint256(price);
    }
    
    function pay(
        uint256 payTokenType,
        uint256 cTokenType,
        uint256 itemCount,
        string calldata kAddress
    ) external payable whenNotPaused {
        require(itemCount > 1000000, "Must purchase more than 0.01 items (itemCount/10**8 ");
        uint256 cTokenPrice = cTokenUsdPrices[cTokenType];
        require(cTokenPrice > 0, "Invalid cToken");

        TokenInfo memory payToken = tokens[payTokenType];
        require(payToken.tokenAddress != address(0) || payTokenType == 1, "Invalid payToken");

        uint256 totalUsdCostCents = (cTokenPrice * itemCount) / 1e8;
        uint256 totalAmountInToken;

        if (payToken.isStablecoin) {
            totalAmountInToken = totalUsdCostCents * (10**payToken.decimals) / 1e2; // Adjust for decimals
        } else {
            (, int256 price,,,) = payToken.priceFeed.latestRoundData();
            require(price > 0, "Invalid price");
            uint256 tokenPrice = uint256(price);
            unchecked {
                totalAmountInToken = (totalUsdCostCents * 10**(payToken.decimals + 6)) / tokenPrice;
            }
        }

        if (payTokenType == 1) {
            require(msg.value >= totalAmountInToken, "Insufficient ETH");
            uint256 excess = msg.value - totalAmountInToken;
            if (excess > 0) {
                (bool sent, ) = msg.sender.call{value: excess}("");
                require(sent, "Failed to send excess ETH");
            }
        } else {
            require(msg.value == 0, "ETH not accepted");
            IERC20(payToken.tokenAddress).safeTransferFrom(msg.sender, address(this), totalAmountInToken);
        }

        emit PaymentMade(msg.sender, payTokenType, cTokenType, kAddress, itemCount);
    }

    function setCTokenUsdPrice(uint256 cTokenType, uint256 usdPriceInCents) external onlyOwner {
        cTokenUsdPrices[cTokenType] = usdPriceInCents;
    }

    function addPaymentToken(
        uint256 payTokenType,
        address tokenAddress,
        address priceFeedAddress,
        bool isStablecoin
    ) external onlyOwner {
        require(tokens[payTokenType].tokenAddress == address(0), "Token type already exists");
        uint8 tokenDecimals = IERC20Metadata(tokenAddress).decimals();
        tokens[payTokenType] = TokenInfo(
            tokenAddress,
            isStablecoin ? AggregatorV3Interface(address(0)) : AggregatorV3Interface(priceFeedAddress),
            isStablecoin,
            tokenDecimals
        );
        unchecked { ++currencyCount; }
    }

    function withdrawTokens(uint256 payTokenType) external onlyOwner {
        TokenInfo storage token = tokens[payTokenType];
        require(token.tokenAddress != address(0), "Invalid token type");
        IERC20 erc20Token = IERC20(token.tokenAddress);
        uint256 tokenBalance = erc20Token.balanceOf(address(this));
        require(tokenBalance > 0, "No tokens to withdraw");
        erc20Token.safeTransfer(owner, tokenBalance);
    }

    function withdrawETH() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No ETH to withdraw");
        payable(owner).transfer(balance);
    }

    function togglePause() external onlyOwner {
        if (paused()) {
            _unpause();
        } else {
            _pause();
        }
    }
}
